use super::conversion::{hsl_to_rgb, rgb_to_hsl};
use super::types::RGB;

pub(crate) fn adjust_brightness(rgb: RGB, factor: f32) -> RGB {
    RGB::new(
        clamp_unit(rgb.r * factor),
        clamp_unit(rgb.g * factor),
        clamp_unit(rgb.b * factor),
    )
}

pub(crate) fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
    let mut hsl = rgb_to_hsl(rgb);
    hsl.s = clamp_unit(hsl.s * factor);
    hsl_to_rgb(hsl)
}

pub(crate) fn grayscale(rgb: RGB) -> RGB {
    let gray = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
    RGB::new(gray, gray, gray)
}

pub(crate) fn invert(rgb: RGB) -> RGB {
    RGB::new(1.0 - rgb.r, 1.0 - rgb.g, 1.0 - rgb.b)
}

pub(crate) fn color_distance(a: RGB, b: RGB) -> f32 {
    let dr = a.r - b.r;
    let dg = a.g - b.g;
    let db = a.b - b.b;
    (dr * dr + dg * dg + db * db).sqrt()
}

fn clamp_unit(value: f32) -> f32 {
    value.clamp(0.0, 1.0)
}

