#[path = "src/lib.rs"]
mod test20_output;

use std::env;
use std::io::{self, Write};

use test20_output::color::{format_cpp_float, ColorConverter, RGB};

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut colors = vec![
        RGB::new(0.1, 0.2, 0.3),
        RGB::new(0.4, 0.5, 0.6),
        RGB::new(0.7, 0.2, 0.1),
        RGB::new(0.3, 0.8, 0.4),
        RGB::new(0.9, 0.1, 0.8),
    ];

    let mut index = 1usize;
    while index + 2 < args.len() {
        let r: f32 = args[index].parse().unwrap();
        let g: f32 = args[index + 1].parse().unwrap();
        let b: f32 = args[index + 2].parse().unwrap();
        colors.push(RGB::new(r, g, b));
        index += 3;
    }

    let first = colors[0];
    let mut stdout = io::BufWriter::new(io::stdout().lock());

    for (color_index, rgb) in colors.iter().copied().enumerate() {
        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);
        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);
        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);
        let gray = ColorConverter::grayscale(rgb);
        let inverted = ColorConverter::invert(rgb);

        let mut line = String::with_capacity(256);
        line.push_str("Color ");
        line.push_str(&color_index.to_string());
        line.push_str(": ");

        push_rgb(&mut line, rgb);
        push_hsl(&mut line, hsl.h, hsl.s, hsl.l);
        push_hsl(&mut line, hsv.h, hsv.s, hsv.v);
        push_cmyk(&mut line, cmyk.c, cmyk.m, cmyk.y, cmyk.k);
        push_hsl(&mut line, yuv.y, yuv.u, yuv.v);
        push_rgb(&mut line, bright);
        push_rgb(&mut line, dark);
        push_rgb(&mut line, saturated);
        push_rgb(&mut line, gray);
        push_rgb(&mut line, inverted);

        if color_index + 1 == colors.len() && colors.len() > 1 {
            push_value(&mut line, ColorConverter::color_distance(rgb, first));
        }

        writeln!(stdout, "{line}").unwrap();
    }
}

fn push_rgb(line: &mut String, rgb: RGB) {
    push_value(line, rgb.r);
    push_value(line, rgb.g);
    push_value(line, rgb.b);
}

fn push_hsl(line: &mut String, first: f32, second: f32, third: f32) {
    push_value(line, first);
    push_value(line, second);
    push_value(line, third);
}

fn push_cmyk(line: &mut String, c: f32, m: f32, y: f32, k: f32) {
    push_value(line, c);
    push_value(line, m);
    push_value(line, y);
    push_value(line, k);
}

fn push_value(line: &mut String, value: f32) {
    line.push_str(&format_cpp_float(value));
    line.push(' ');
}

