use super::types::{CMYK, HSL, HSV, RGB, YUV};

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: RGB) -> HSL {
        rgb_to_hsl(rgb)
    }

    pub fn rgb_to_hsv(rgb: RGB) -> HSV {
        rgb_to_hsv(rgb)
    }

    pub fn rgb_to_cmyk(rgb: RGB) -> CMYK {
        rgb_to_cmyk(rgb)
    }

    pub fn rgb_to_yuv(rgb: RGB) -> YUV {
        rgb_to_yuv(rgb)
    }

    pub fn adjust_brightness(rgb: RGB, factor: f32) -> RGB {
        super::operations::adjust_brightness(rgb, factor)
    }

    pub fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
        super::operations::adjust_saturation(rgb, factor)
    }

    pub fn grayscale(rgb: RGB) -> RGB {
        super::operations::grayscale(rgb)
    }

    pub fn invert(rgb: RGB) -> RGB {
        super::operations::invert(rgb)
    }

    pub fn color_distance(a: RGB, b: RGB) -> f32 {
        super::operations::color_distance(a, b)
    }
}

pub(crate) fn rgb_to_hsl(rgb: RGB) -> HSL {
    let max = rgb.r.max(rgb.g.max(rgb.b));
    let min = rgb.r.min(rgb.g.min(rgb.b));
    let delta = max - min;
    let lightness = (max + min) / 2.0;

    if delta == 0.0 {
        return HSL::new(0.0, 0.0, lightness);
    }

    let saturation = delta / (1.0 - (2.0 * lightness - 1.0).abs());
    let hue = calculate_hue(rgb, max, delta);
    HSL::new(hue, saturation, lightness)
}

pub(crate) fn rgb_to_hsv(rgb: RGB) -> HSV {
    let max = rgb.r.max(rgb.g.max(rgb.b));
    let min = rgb.r.min(rgb.g.min(rgb.b));
    let delta = max - min;

    if delta == 0.0 {
        return HSV::new(0.0, 0.0, max);
    }

    let saturation = if max == 0.0 { 0.0 } else { delta / max };
    let hue = calculate_hue(rgb, max, delta);
    HSV::new(hue, saturation, max)
}

pub(crate) fn rgb_to_cmyk(rgb: RGB) -> CMYK {
    let black = 1.0 - rgb.r.max(rgb.g.max(rgb.b));
    if black == 1.0 {
        return CMYK::new(0.0, 0.0, 0.0, 1.0);
    }

    let inv = 1.0 - black;
    CMYK::new(
        (1.0 - rgb.r - black) / inv,
        (1.0 - rgb.g - black) / inv,
        (1.0 - rgb.b - black) / inv,
        black,
    )
}

pub(crate) fn rgb_to_yuv(rgb: RGB) -> YUV {
    YUV::new(
        0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b,
        -0.147 * rgb.r - 0.289 * rgb.g + 0.436 * rgb.b,
        0.615 * rgb.r - 0.515 * rgb.g - 0.100 * rgb.b,
    )
}

pub(crate) fn hsl_to_rgb(hsl: HSL) -> RGB {
    if hsl.s == 0.0 {
        return RGB::new(hsl.l, hsl.l, hsl.l);
    }

    let hue = hsl.h / 360.0;
    let q = if hsl.l < 0.5 {
        hsl.l * (1.0 + hsl.s)
    } else {
        hsl.l + hsl.s - hsl.l * hsl.s
    };
    let p = 2.0 * hsl.l - q;

    RGB::new(
        hue_to_rgb(p, q, hue + 1.0 / 3.0),
        hue_to_rgb(p, q, hue),
        hue_to_rgb(p, q, hue - 1.0 / 3.0),
    )
}

fn calculate_hue(rgb: RGB, max: f32, delta: f32) -> f32 {
    let mut hue = if max == rgb.r {
        60.0 * (((rgb.g - rgb.b) / delta) % 6.0)
    } else if max == rgb.g {
        60.0 * (((rgb.b - rgb.r) / delta) + 2.0)
    } else {
        60.0 * (((rgb.r - rgb.g) / delta) + 4.0)
    };

    if hue < 0.0 {
        hue += 360.0;
    }

    hue
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

