pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let scientific = format!("{value:.5e}");
    let (mantissa, exponent_text) = scientific
        .split_once('e')
        .expect("scientific format should contain an exponent");
    let exponent: i32 = exponent_text
        .parse()
        .expect("Rust scientific formatter should produce a valid exponent");

    if exponent < -4 || exponent >= 6 {
        let mut trimmed = mantissa.to_string();
        trim_fractional_zeros(&mut trimmed);
        let exponent_sign = if exponent < 0 { '-' } else { '+' };
        let exponent_value = exponent.abs();
        return format!("{trimmed}e{exponent_sign}{exponent_value:02}");
    }

    let decimals = (6 - (exponent + 1)) as usize;
    let mut fixed = format!("{value:.decimals$}");
    trim_fractional_zeros(&mut fixed);
    fixed
}

fn trim_fractional_zeros(text: &mut String) {
    if !text.contains('.') {
        return;
    }

    while text.ends_with('0') {
        text.pop();
    }

    if text.ends_with('.') {
        text.pop();
    }
}

