use std::ffi::{c_char, c_int};

const FORMAT_SPECIFIER: &[u8] = b"%.6g\0";

extern "C" {
    fn snprintf(buffer: *mut c_char, size: usize, format: *const c_char, ...) -> c_int;
}

pub fn format_cpp_float(value: f32) -> String {
    let mut buffer = [0u8; 64];
    let written = unsafe {
        snprintf(
            buffer.as_mut_ptr().cast(),
            buffer.len(),
            FORMAT_SPECIFIER.as_ptr().cast(),
            f64::from(value),
        )
    };

    if written < 0 {
        panic!("snprintf failed to format float");
    }

    let length = usize::try_from(written).expect("formatted length should fit in usize");
    let text = &buffer[..length];
    std::str::from_utf8(text)
        .expect("snprintf should produce valid UTF-8 for %.6g")
        .to_owned()
}

