use crate::color::types::{CMYK, HSL, HSV, RGB, YUV};

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: RGB) -> HSL {
        let max = max3(rgb.r, rgb.g, rgb.b);
        let min = min3(rgb.r, rgb.g, rgb.b);
        let delta = max - min;
        let l = (max + min) / 2.0;

        if delta == 0.0 {
            return HSL { h: 0.0, s: 0.0, l };
        }

        let s = if l < 0.5 {
            delta / (max + min)
        } else {
            delta / (2.0 - max - min)
        };
        let h = hue_from_rgb(rgb, max, delta);
        HSL { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: RGB) -> HSV {
        let max = max3(rgb.r, rgb.g, rgb.b);
        let min = min3(rgb.r, rgb.g, rgb.b);
        let delta = max - min;

        if delta == 0.0 {
            return HSV {
                h: 0.0,
                s: 0.0,
                v: max,
            };
        }

        let s = if max == 0.0 { 0.0 } else { delta / max };
        let h = hue_from_rgb(rgb, max, delta);
        HSV { h, s, v: max }
    }

    pub fn rgb_to_cmyk(rgb: RGB) -> CMYK {
        let max = max3(rgb.r, rgb.g, rgb.b);
        if max == 0.0 {
            return CMYK {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k: 1.0,
            };
        }

        let k = 1.0 - max;
        let denom = 1.0 - k;
        CMYK {
            c: (1.0 - rgb.r - k) / denom,
            m: (1.0 - rgb.g - k) / denom,
            y: (1.0 - rgb.b - k) / denom,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: RGB) -> YUV {
        YUV {
            y: 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b,
            u: -0.147 * rgb.r - 0.289 * rgb.g + 0.436 * rgb.b,
            v: 0.615 * rgb.r - 0.515 * rgb.g - 0.100 * rgb.b,
        }
    }

    pub fn adjust_brightness(rgb: RGB, factor: f32) -> RGB {
        RGB {
            r: clamp01(rgb.r * factor),
            g: clamp01(rgb.g * factor),
            b: clamp01(rgb.b * factor),
        }
    }

    pub fn adjust_saturation(rgb: RGB, factor: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        hsl_to_rgb(hsl)
    }

    pub fn grayscale(rgb: RGB) -> RGB {
        let gray = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
        RGB {
            r: gray,
            g: gray,
            b: gray,
        }
    }

    pub fn invert(rgb: RGB) -> RGB {
        RGB {
            r: 1.0 - rgb.r,
            g: 1.0 - rgb.g,
            b: 1.0 - rgb.b,
        }
    }

    pub fn color_distance(a: RGB, b: RGB) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }
}

fn hsl_to_rgb(hsl: HSL) -> RGB {
    if hsl.s == 0.0 {
        return RGB {
            r: hsl.l,
            g: hsl.l,
            b: hsl.l,
        };
    }

    let q = if hsl.l < 0.5 {
        hsl.l * (1.0 + hsl.s)
    } else {
        hsl.l + hsl.s - hsl.l * hsl.s
    };
    let p = 2.0 * hsl.l - q;
    let hk = hsl.h / 360.0;

    RGB {
        r: hue_to_rgb(p, q, hk + 1.0 / 3.0),
        g: hue_to_rgb(p, q, hk),
        b: hue_to_rgb(p, q, hk - 1.0 / 3.0),
    }
}

fn hue_from_rgb(rgb: RGB, max: f32, delta: f32) -> f32 {
    let mut hue = if max == rgb.r {
        60.0 * ((rgb.g - rgb.b) / delta % 6.0)
    } else if max == rgb.g {
        60.0 * ((rgb.b - rgb.r) / delta + 2.0)
    } else {
        60.0 * ((rgb.r - rgb.g) / delta + 4.0)
    };

    if hue < 0.0 {
        hue += 360.0;
    }

    hue
}

fn clamp01(value: f32) -> f32 {
    if value < 0.0 {
        0.0
    } else if value > 1.0 {
        1.0
    } else {
        value
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }

    if t < 1.0 / 6.0 {
        p + (q - p) * 6.0 * t
    } else if t < 1.0 / 2.0 {
        q
    } else if t < 2.0 / 3.0 {
        p + (q - p) * (2.0 / 3.0 - t) * 6.0
    } else {
        p
    }
}

fn max3(a: f32, b: f32, c: f32) -> f32 {
    cxx_max(cxx_max(a, b), c)
}

fn min3(a: f32, b: f32, c: f32) -> f32 {
    cxx_min(cxx_min(a, b), c)
}

fn cxx_max(a: f32, b: f32) -> f32 {
    if a < b { b } else { a }
}

fn cxx_min(a: f32, b: f32) -> f32 {
    if b < a { b } else { a }
}

