pub fn parse_cxx_float(input: &str) -> f32 {
    let trimmed = trim_start_ascii_whitespace(input);
    let prefix_len = parse_prefix_len(trimmed);
    if prefix_len == 0 {
        panic!("invalid float literal");
    }

    trimmed[..prefix_len]
        .parse::<f32>()
        .unwrap_or_else(|_| panic!("invalid float literal"))
}

fn trim_start_ascii_whitespace(input: &str) -> &str {
    input.trim_start_matches(|ch: char| ch.is_ascii_whitespace())
}

fn parse_prefix_len(input: &str) -> usize {
    if input.is_empty() {
        return 0;
    }

    let bytes = input.as_bytes();
    let mut index = 0;

    if matches!(bytes[index], b'+' | b'-') {
        index += 1;
    }

    if let Some(len) = parse_inf_len(input, index) {
        return len;
    }

    if let Some(len) = parse_nan_len(input, index) {
        return len;
    }

    let start = index;
    let mut has_digits = false;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        index += 1;
        has_digits = true;
    }

    if index < bytes.len() && bytes[index] == b'.' {
        index += 1;
        while index < bytes.len() && bytes[index].is_ascii_digit() {
            index += 1;
            has_digits = true;
        }
    }

    if !has_digits {
        return 0;
    }

    let exponent_start = index;
    if index < bytes.len() && matches!(bytes[index], b'e' | b'E') {
        let mut exp_index = index + 1;
        if exp_index < bytes.len() && matches!(bytes[exp_index], b'+' | b'-') {
            exp_index += 1;
        }

        let digits_start = exp_index;
        while exp_index < bytes.len() && bytes[exp_index].is_ascii_digit() {
            exp_index += 1;
        }

        if exp_index > digits_start {
            index = exp_index;
        } else {
            index = exponent_start;
        }
    }

    if index == start { 0 } else { index }
}

fn parse_inf_len(input: &str, start: usize) -> Option<usize> {
    let tail = &input[start..];
    if tail.len() >= 8 && tail[..8].eq_ignore_ascii_case("infinity") {
        Some(start + 8)
    } else if tail.len() >= 3 && tail[..3].eq_ignore_ascii_case("inf") {
        Some(start + 3)
    } else {
        None
    }
}

fn parse_nan_len(input: &str, start: usize) -> Option<usize> {
    let tail = &input[start..];
    if tail.len() < 3 || !tail[..3].eq_ignore_ascii_case("nan") {
        return None;
    }

    let mut index = start + 3;
    let bytes = input.as_bytes();
    if index < bytes.len() && bytes[index] == b'(' {
        index += 1;
        while index < bytes.len() && bytes[index] != b')' {
            index += 1;
        }
        if index < bytes.len() && bytes[index] == b')' {
            index += 1;
        }
    }

    Some(index)
}

