const PRECISION: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            "-0".to_string()
        } else {
            "0".to_string()
        };
    }

    let scientific = format!("{:.*e}", PRECISION - 1, value as f64);
    let (mantissa_raw, exponent_raw) = scientific
        .split_once('e')
        .expect("scientific format must contain an exponent");
    let exponent: i32 = exponent_raw
        .parse()
        .expect("scientific exponent must be a valid integer");

    if exponent < -4 || exponent >= PRECISION as i32 {
        let mantissa = trim_fraction(mantissa_raw);
        let sign = if exponent < 0 { '-' } else { '+' };
        let abs_exponent = exponent.abs();
        format!("{mantissa}e{sign}{abs_exponent:02}")
    } else {
        let decimals = (PRECISION as i32 - exponent - 1).max(0) as usize;
        let fixed = format!("{:.*}", decimals, value as f64);
        trim_fraction(&fixed)
    }
}

fn trim_fraction(input: &str) -> String {
    if !input.contains('.') {
        return input.to_string();
    }

    let mut end = input.len();
    let bytes = input.as_bytes();
    while end > 0 && bytes[end - 1] == b'0' {
        end -= 1;
    }
    if end > 0 && bytes[end - 1] == b'.' {
        end -= 1;
    }

    input[..end].to_string()
}

